# ==========================================================
# OFFLINE ČÍTANIA NA 7 DNÍ
# ==========================================================
CITANIA_OFFLINE_DNI = 7
CITANIA_OFFLINE_DIR_NAME = "offline_citania"
# Koľko dní dozadu sa v offline cache ponecháva (1 = ponechá sa včerajšok, staršie sa mažú)
CITANIA_OFFLINE_PONECHAT_DNI_DOZADU = 1

def ziskaj_offline_citania_dir(song_folder: Path | str | None = None, vytvor: bool = True) -> Path:
    """
    Vráti adresár pre offline cache čítaní.

    Priorita:
    1) Ak je zadaný song_folder (Nastavenia → Pokročilé → Umiestnenie súborov), cache je
       jeho podpriečinok `offline_citania` – presne tam, kde sú aj piesne:
       - C:\\Kinak\\piesne       →  C:\\Kinak\\piesne\\offline_citania
       - D:\\Data\\MojePiesne    →  D:\\Data\\MojePiesne\\offline_citania
       Do priečinka piesní aplikácia zapisuje aj citania.txt, takže je zaručene zapisovateľný.
    2) Ak song_folder nie je zadaný a existuje LOCAL_SONG_FOLDER (BASE_DIR/piesne) →
       portable režim → BASE_DIR/piesne/offline_citania
    3) Štandard: CONFIG_DIR/offline_citania (inštalovaný režim, %LOCALAPPDATA%\\Kinak)

    Staršie umiestnenia (offline_citania vedľa priečinka piesní, BASE_DIR/offline_citania) sa
    už na zápis nepoužívajú; čítanie ich stále prehľadáva – pozri
    _vsetky_mozne_offline_cache_priecinky().

    Kandidát sa použije, iba ak už existuje on alebo jeho rodič (nevytvárajú sa celé
    neexistujúce stromy) a nie je priamo v koreni disku.
    Ak je `vytvor=False`, priečinok sa nevytvára (vhodné pre zobrazenie cesty a čítanie);
    pri `vytvor=True` sa vytvorí a vráti sa prvý použiteľný kandidát.
    """
    kandidati: list[Path] = []

    # 1) Explicitný song_folder z nastavení – cache priamo v ňom
    if song_folder:
        try:
            sf = Path(song_folder)
            if sf.is_file():
                sf = sf.parent
            kandidati.append(sf / CITANIA_OFFLINE_DIR_NAME)
        except Exception as e:
            log_exception("ziskaj_offline_citania_dir: spracovanie song_folder zlyhalo", e)

    # 2) Portable detekcia – ak je vedľa exe priečinok piesne, sme v C:\Kinak režime
    try:
        if LOCAL_SONG_FOLDER.is_dir():
            kandidati.append(LOCAL_SONG_FOLDER / CITANIA_OFFLINE_DIR_NAME)
    except Exception:
        pass

    # 3) Štandardný AppData priečinok
    kandidati.append(CONFIG_DIR / CITANIA_OFFLINE_DIR_NAME)

    for cand in kandidati:
        try:
            # Vyhni sa zápisu do koreňa disku (C:\\offline_citania)
            if len(cand.parts) >= 2 and cand.parent == Path(cand.anchor):
                continue
            if not (cand.exists() or cand.parent.exists()):
                continue
            if vytvor:
                cand.mkdir(parents=True, exist_ok=True)
            return cand
        except Exception:
            continue

    # Fallback – temp
    try:
        fallback = Path(tempfile.gettempdir()) / f"Kinak_{CITANIA_OFFLINE_DIR_NAME}"
        if vytvor:
            fallback.mkdir(parents=True, exist_ok=True)
        return fallback
    except Exception as e2:
        log_exception("ziskaj_offline_citania_dir: fallback mkdir zlyhal", e2)
        return CONFIG_DIR / CITANIA_OFFLINE_DIR_NAME

def cesta_offline_citania_pre_datum(datum: date, cache_dir: Path | str | None = None, song_folder: Path | str | None = None) -> Path:
    """Vráti cestu k offline súboru pre daný dátum: YYYY-MM-DD.txt"""
    if cache_dir is None:
        cache_dir = ziskaj_offline_citania_dir(song_folder, vytvor=False)
    cache_dir = Path(cache_dir)
    return cache_dir / f"{datum.isoformat()}.txt"

def _vsetky_mozne_offline_cache_priecinky(song_folder: Path | str | None = None) -> list[Path]:
    """
    Vráti zoznam všetkých miest, kde môže byť offline cache (pre čítanie s fallbackom).
    Aktuálne umiestnenia sú prvé, staršie (iba na čítanie) nasledujú za nimi.
    """
    zoznam: list[Path] = []
    seen = set()
    def pridaj(p: Path):
        try:
            rp = p.resolve() if p.exists() else p
            key = str(rp).lower()
            if key not in seen:
                seen.add(key)
                zoznam.append(p)
        except Exception:
            if p not in zoznam:
                zoznam.append(p)
    # 1) aktuálne: podľa song_folder
    if song_folder:
        try:
            sf = Path(song_folder)
            if sf.is_file():
                sf = sf.parent
            pridaj(sf / CITANIA_OFFLINE_DIR_NAME)
        except Exception:
            sf = None
    else:
        sf = None
    # 2) aktuálne: portable (BASE_DIR/piesne/offline_citania)
    try:
        if LOCAL_SONG_FOLDER.is_dir():
            pridaj(LOCAL_SONG_FOLDER / CITANIA_OFFLINE_DIR_NAME)
    except Exception:
        pass
    # 3) aktuálne: AppData
    pridaj(CONFIG_DIR / CITANIA_OFFLINE_DIR_NAME)
    # 4) staršie umiestnenia (už sa doň nezapisuje, len číta): cache vedľa priečinka piesní
    if sf is not None:
        pridaj(sf.parent / CITANIA_OFFLINE_DIR_NAME)
    try:
        if LOCAL_SONG_FOLDER.is_dir():
            pridaj(BASE_DIR / CITANIA_OFFLINE_DIR_NAME)
    except Exception:
        pass
    # 5) temp fallback
    pridaj(Path(tempfile.gettempdir()) / f"Kinak_{CITANIA_OFFLINE_DIR_NAME}")
    return zoznam

def nacitaj_citania_z_offline_cache(datum: date, cache_dir: Path | str | None = None, song_folder: Path | str | None = None) -> str | None:
    """Načíta text čítaní z offline cache – skúša všetky možné umiestnenia (nové aj staré)."""
    try:
        if cache_dir is not None:
            cesty = [cesta_offline_citania_pre_datum(datum, cache_dir)]
        else:
            cesty = [cesta_offline_citania_pre_datum(datum, cd) for cd in _vsetky_mozne_offline_cache_priecinky(song_folder)]

            def _mtime(p: Path) -> float:
                try:
                    return p.stat().st_mtime if p.is_file() else -1.0
                except Exception:
                    return -1.0
            # Najčerstvejší súbor ako prvý (pri zhode ostáva poradie podľa priority umiestnení)
            cesty.sort(key=_mtime, reverse=True)

        for cesta in cesty:
            if not cesta.is_file():
                continue
            # Skús UTF-8 (utf-8-sig zvláda aj súbor bez BOM a BOM odstráni), potom cp1250
            for enc in ("utf-8-sig", "cp1250"):
                try:
                    with cesta.open("r", encoding=enc) as f:
                        text = f.read()
                except Exception:
                    continue
                if len(text) >= 200:
                    return text
                break  # súbor sa načítal, ale je príliš krátky – iné kódovanie ho nezlepší
        return None
    except Exception as e:
        log_exception(f"nacitaj_citania_z_offline_cache: {datum}", e)
        return None

def vycisti_stare_offline_citania(
    song_folder: Path | str | None = None,
    zachovat: set | None = None,
    ponechat_dni_dozadu: int = CITANIA_OFFLINE_PONECHAT_DNI_DOZADU,
) -> int:
    """
    Zmaže staré offline čítania: súbory YYYY-MM-DD.txt s dátumom staršie než
    (dnes - ponechat_dni_dozadu), teda pri predvolenej hodnote 1 ostáva včerajšok, dnešok a budúce dni.

    Čistí všetky miesta, kde sa cache číta (aj staršie umiestnenia vedľa priečinka piesní).
    Maže sa len súbor, ktorého názov presne zodpovedá YYYY-MM-DD.txt; iné súbory sa nedotknú.
    `zachovat` je množina dátumov, ktoré sa nemajú mazať (napr. práve stiahnuté dni).
    Chyby sa len logujú. Vráti počet zmazaných súborov.
    """
    zmazane = 0
    try:
        hranica = date.today() - timedelta(days=max(0, int(ponechat_dni_dozadu)))
        for cd in _vsetky_mozne_offline_cache_priecinky(song_folder):
            try:
                if not cd.is_dir():
                    continue
                for f in cd.glob("*.txt"):
                    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", f.stem):
                        continue
                    try:
                        datum = date.fromisoformat(f.stem)
                    except ValueError:
                        continue
                    if datum >= hranica or (zachovat and datum in zachovat):
                        continue
                    try:
                        if f.is_file():
                            f.unlink()
                            zmazane += 1
                    except Exception as e:
                        log_exception(f"vycisti_stare_offline_citania: mazanie {f} zlyhalo", e)
            except Exception as e:
                log_exception(f"vycisti_stare_offline_citania: priečinok {cd} zlyhal", e)
        if zmazane:
            log_info(f"Offline čítania: zmazaných {zmazane} starých súborov (staršie než {hranica.isoformat()}).")
    except Exception as e:
        log_exception("vycisti_stare_offline_citania zlyhalo", e)
    return zmazane

def uloz_citania_do_offline_cache(datum: date, text: str, cache_dir: Path | str | None = None, song_folder: Path | str | None = None) -> bool:
    """Uloží text čítaní do offline cache."""
    try:
        if cache_dir is None:
            cache_dir = ziskaj_offline_citania_dir(song_folder)
        cesta = cesta_offline_citania_pre_datum(datum, cache_dir)
        cesta.parent.mkdir(parents=True, exist_ok=True)
        _zapis_text_atomicky(cesta, text, encoding="utf-8")
        return True
    except Exception as e:
        log_exception(f"uloz_citania_do_offline_cache: {datum}", e)
        return False

def zisti_datum_citania_v_subore(cesta: Path | str) -> date | None:
    """Prečíta dátum z hlavičky citania.txt (samostatný riadok DD.MM.RRRR). None, ak sa nenájde."""
    try:
        with Path(cesta).open("r", encoding="utf-8-sig", errors="replace") as f:
            for _ in range(20):
                riadok = f.readline()
                if not riadok:
                    break
                m = re.fullmatch(r"\s*(\d{2})\.(\d{2})\.(\d{4})\s*", riadok)
                if m:
                    return date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
    except Exception:
        pass
    return None

def skontroluj_citania_txt_pri_starte(song_folder: Path | str | None = None) -> bool:
    """
    Kontrola citania.txt pri štarte podľa zadania:

    - Ak súbor citania.txt pri štarte neexistuje → nerob nič, pokračuj v spustení appky.
    - Ak citania.txt má dátum v minulosti alebo v budúcnosti:
        → ak je dnešný deň uložený v priečinku offline_citania/, nahradí ho dneškom
        → inak ponechá pôvodný (starý) obsah
    - Ak má dátum dnes → ponechá ho.

    Vracia True, ak došlo k nahradeniu, inak False.
    """
    try:
        if song_folder is None:
            # Ak nie je zadaný priečinok, nevieme určiť cestu k citania.txt – nerob nič
            # (volajúci by mal vždy poslať song_folder_path)
            return False

        sf = Path(song_folder)
        if sf.is_file():
            sf = sf.parent

        if not sf.is_dir():
            return False

        citania_cesta = sf / "citania.txt"

        # 1) Ak súbor neexistuje → nerob nič
        if not citania_cesta.is_file():
            log_info(f"skontroluj_citania_txt_pri_starte: {citania_cesta} neexistuje – pokračujem bez zmeny.")
            return False

        datum_suboru = zisti_datum_citania_v_subore(citania_cesta)

        # Ak sa dátum nepodarí prečítať, ponechaj pôvodný obsah
        if datum_suboru is None:
            log_info(f"skontroluj_citania_txt_pri_starte: {citania_cesta} bez dátumu – ponechávam.")
            return False

        dnes = date.today()

        # Ak je dátum dnes, nič nerob
        if datum_suboru == dnes:
            return False

        # Minulosť alebo budúcnosť → skús offline cache pre dnes
        log_info(
            f"skontroluj_citania_txt_pri_starte: citania.txt má dátum {datum_suboru.strftime('%d.%m.%Y')} "
            f"(dnes {dnes.strftime('%d.%m.%Y')}) – hľadám v offline_citania/."
        )

        cache_text = nacitaj_citania_z_offline_cache(dnes, song_folder=sf)

        if cache_text:
            try:
                _zapis_text_atomicky(citania_cesta, cache_text, encoding="utf-8")
                log_info(f"skontroluj_citania_txt_pri_starte: citania.txt nahradený dneškom {dnes.isoformat()} z offline cache.")
                return True
            except Exception as e:
                log_exception("skontroluj_citania_txt_pri_starte: zápis z offline cache zlyhal", e)
                return False
        else:
            log_info(
                f"skontroluj_citania_txt_pri_starte: offline cache pre {dnes.isoformat()} neexistuje – "
                f"ponechaný pôvodný obsah z {datum_suboru.strftime('%d.%m.%Y')}."
            )
            return False

    except Exception as e:
        log_exception("skontroluj_citania_txt_pri_starte zlyhalo", e)
        return False


def stiahni_citania_na_7_dni(
    pociatocny_datum: date,
    hlavny_vystup: Path | str,
    cache_dir: Path | str | None = None,
    progress_callback=None,
    song_folder: Path | str | None = None,
) -> dict:
    """
    Stiahne čítania na 7 dní od pociatocny_datum (vrátane).
    - Každý deň uloží do cache_dir/YYYY-MM-DD.txt
    - Prvý deň (dnes) zároveň skopíruje do hlavny_vystup (citania.txt)
    - Vracia dict s výsledkom: {"uspech": bool, "celkovo": 7, "stiahnute": int, "chyby": int, "subory": [...],
      "zrusene": bool}. Pri zrušení (tlačidlo Zrušiť / ukončenie aplikácie) sa slučka zastaví a vráti sa
      čiastočný výsledok; už uložené dni zostávajú.
    """
    _over_gregoriansky_datum(pociatocny_datum)
    if chybaju_kniznice_pre_stahovanie():
        return {"uspech": False, "celkovo": CITANIA_OFFLINE_DNI, "stiahnute": 0, "chyby": CITANIA_OFFLINE_DNI, "subory": [], "chybaju_kniznice": True}

    if cache_dir is None:
        cache_dir = ziskaj_offline_citania_dir(song_folder)
    cache_dir = Path(cache_dir)
    try:
        cache_dir.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        log_exception("stiahni_citania_na_7_dni: mkdir cache_dir zlyhal", e)
        return {"uspech": False, "celkovo": CITANIA_OFFLINE_DNI, "stiahnute": 0, "chyby": CITANIA_OFFLINE_DNI, "subory": []}

    hlavny_vystup = Path(hlavny_vystup)
    stiahnute = 0
    chyby = 0
    subory = []
    stiahnute_datumy = []

    zrusene = False
    try:
        for i in range(CITANIA_OFFLINE_DNI):
            _over_zrusenie()
            datum = pociatocny_datum + timedelta(days=i)
            cache_path = cache_dir / f"{datum.isoformat()}.txt"

            # Progress hlásenie
            if callable(progress_callback):
                update_progress(progress_callback, f"Sťahujem {datum.strftime('%d.%m.%Y')} ({i+1}/{CITANIA_OFFLINE_DNI})...", i, CITANIA_OFFLINE_DNI)

            uspech = False
            try:
                uspech = stiahni_citania_z_lc_kbs(datum, cache_path)
            except Exception as e:
                log_exception(f"stiahni_citania_na_7_dni: {datum}", e)
                uspech = False

            if uspech and cache_path.is_file():
                stiahnute += 1
                subory.append(cache_path.name)
                stiahnute_datumy.append(datum)
                # Prvý deň -> hlavný súbor
                if i == 0:
                    try:
                        # Atómicky skopírovať obsah cache do hlavného výstupu
                        with cache_path.open("r", encoding="utf-8") as src:
                            text = src.read()
                        _zapis_text_atomicky(hlavny_vystup, text, encoding="utf-8")
                    except Exception as e:
                        log_exception(f"stiahni_citania_na_7_dni: kopírovanie do hlavného súboru {hlavny_vystup}", e)
            else:
                chyby += 1
                # Ak stiahnutie zlyhalo, ale v cache už niečo staršie existuje, ponecháme ho (offline fallback)

            # Malé oneskorenie medzi požiadavkami, aby sme nezaťažili server
            if i < CITANIA_OFFLINE_DNI - 1:
                _cakaj_s_moznostou_zrusenia(0.6)

            if callable(progress_callback):
                update_progress(progress_callback, f"Spracované {i+1}/{CITANIA_OFFLINE_DNI}", i+1, CITANIA_OFFLINE_DNI)
    except _StahovanieZrusene:
        zrusene = True
        log_info(f"stiahni_citania_na_7_dni: zrušené po {stiahnute} stiahnutých dňoch.")

    uspech_celkovo = stiahnute > 0
    return {
        "uspech": uspech_celkovo,
        "celkovo": CITANIA_OFFLINE_DNI,
        "stiahnute": stiahnute,
        "chyby": chyby,
        "subory": subory,
        "stiahnute_datumy": stiahnute_datumy,
        "zrusene": zrusene,
    }

LC_KBS_USER_AGENTS: list[str] = [
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36",
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:128.0) Gecko/20100101 Firefox/128.0",
    "Mozilla/5.0 (Macintosh; Intel Mac OS X 14_6) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.0 Safari/605.1.15",
]

def _validuj_rok_pre_gui(hodnota: object) -> int:
    try:
        rok = int(str(hodnota).strip())
    except Exception:
        raise ValueError(f"Rok musí byť celé číslo, zadané: {hodnota!r}")
    _over_gregoriansky_rok(rok)
    return rok


def _vyber_user_agent() -> str:
    try:
        base = random.choice(LC_KBS_USER_AGENTS)
    except Exception:
        base = LC_KBS_USER_AGENTS[0]
    return f"{base} Kinak/{KINAK_VERSION}"

def _vytvor_lc_kbs_session() -> Any:
    if requests is None:
        return None
    try:
        session = requests.Session()
    except Exception:
        return None
    if HTTPAdapter is not None and Retry is not None:
        try:
            # ZÁMERNE total=0 (žiadny automatický retry na úrovni
            # urllib3/HTTPAdapter). Predtým tu bol nakonfigurovaný aj
            # automatický retry s status_forcelist=LC_KBS_DOCASNE_HTTP_STATUSY,
            # ktorý sa prekrýval s manuálnou 'for pokus in range(...)' slučkou
            # v _stiahni_lc_kbs_soup – obe vrstvy opakovali tie isté dočasné
            # HTTP statusy, čím sa počet skutočných HTTP požiadaviek na jeden
            # dátum násobil (overené testom: až 12 požiadaviek namiesto
            # očakávaných LC_KBS_REFRENY_MAX_POKUSOV=3, pri zlyhávajúcom
            # serveri navyše ~4x dlhšie čakanie kvôli zdvojenému backoffu).
            #
            # Retry je teraz úmyselne JEDINÁ vrstva v manuálnej slučke – tá
            # rieši úplne všetko: dočasné HTTP statusy aj nízkoúrovňové
            # zlyhania spojenia (timeout, výpadok siete, prerušené spojenie).
            # HTTPAdapter tu zostáva výhradne kvôli connection poolingu
            # (pool_connections/pool_maxsize), nie kvôli retry.
            retry = Retry(total=0)
            adapter = HTTPAdapter(max_retries=retry, pool_connections=10, pool_maxsize=10)
            session.mount("https://", adapter)
            session.mount("http://", adapter)
        except Exception:
            pass
    return session



def _lc_kbs_headers(ucel: str = "") -> dict:
    suffix = f" {ucel}" if ucel else ""
    ua = _vyber_user_agent()
    if suffix and suffix not in ua:
        ua = f"{ua}{suffix}"
    return {
        "User-Agent": ua,
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
        "Accept-Language": "sk-SK,sk;q=0.9,en;q=0.8",
        "Cache-Control": "no-cache, no-store, must-revalidate",
        "Pragma": "no-cache",
        "Expires": "0",
    }


def _stiahni_lc_kbs_soup(datum: date, session: Any = None, timeout: tuple[int, int] = (5, 20)) -> Any | None:
    """
    Stiahne a naparsuje stránku lc.kbs.sk pre daný dátum.

    session: voliteľná už existujúca `requests.Session` (napr. vytvorená raz
    na úrovni celej dávky cez `_RefrenyKontext` a zdieľaná pre všetky dátumy
    v dávke – pozri _RefrenyKontext.session). Ak nie je zadaná (None), funkcia
    si pre spätnú kompatibilitu (samostatné volania mimo dávky) vytvorí a na
    konci sama zatvorí VLASTNÚ session – presne ako predtým. Ak JE zadaná,
    funkcia ju NEZATVÁRA (životný cyklus session patrí volajúcemu/dávke).

    Retry je zámerne implementovaný len na JEDNEJ vrstve – v tejto manuálnej
    slučke. HTTPAdapter/urllib3.Retry (nastavený v _vytvor_lc_kbs_session) má
    total=0 a sám nič neopakuje; slúži tam už len na connection pooling.
    Táto slučka preto rieši úplne všetko: dočasné HTTP statusy vrátené
    serverom (LC_KBS_DOCASNE_HTTP_STATUSY) aj nízkoúrovňové zlyhania
    (timeout, výpadok siete, prerušené spojenie) – s osobitným logovaním pre
    každý typ chyby, aby bolo pri diagnostike jasné, kde presne sťahovanie
    zlyhalo. (Predtým tu boli retry vrstvy dve a prekrývali sa – pozri
    komentár v _vytvor_lc_kbs_session.)
    """
    _over_gregoriansky_datum(datum)
    if chybaju_kniznice_pre_stahovanie():
        return None

    requests_module = requests
    beautiful_soup = BeautifulSoup
    assert requests_module is not None and beautiful_soup is not None

    datum_str = datum.strftime("%Y-%m-%d")
    session_vytvorena_lokalne = session is None
    if session_vytvorena_lokalne:
        session = _vytvor_lc_kbs_session()

    request_exception_type = getattr(requests_module, "RequestException", Exception)
    http_error_type = getattr(requests_module, "HTTPError", request_exception_type)
    timeout_type = getattr(requests_module, "Timeout", request_exception_type)
    connection_error_type = getattr(requests_module, "ConnectionError", request_exception_type)

    try:
        for pokus in range(1, LC_KBS_REFRENY_MAX_POKUSOV + 1):
            _over_zrusenie()
            url = f"https://lc.kbs.sk/?den={datum_str}&_={int(time.time())}"
            try:
                headers = _lc_kbs_headers("refreny-zalmov")
                resp = session.get(url, headers=headers, timeout=timeout) if session else requests_module.get(url, headers=headers, timeout=timeout)
                resp.raise_for_status()
                resp.encoding = _zisti_http_kodovanie(resp, "LC-KBS", fallback="utf-8")
                return beautiful_soup(resp.text, "html.parser")

            except http_error_type as e:
                status_code = getattr(getattr(e, "response", None), "status_code", None)
                if status_code in LC_KBS_DOCASNE_HTTP_STATUSY and pokus < LC_KBS_REFRENY_MAX_POKUSOV:
                    log_debug(
                        f"[LC-KBS] Dátum {datum_str}: HTTP {status_code}, "
                        f"skúšam znova ({pokus}/{LC_KBS_REFRENY_MAX_POKUSOV})."
                    )
                    _cakaj_s_moznostou_zrusenia(LC_KBS_REFRENY_RETRY_DELAY_S * pokus)
                    continue

                log_info(
                    f"[LC-KBS] Dátum {datum_str}: server vrátil HTTP {status_code or 'chyba'} "
                    f"po {pokus} pokusoch, refrén preskakujem."
                )
                return None

            except (timeout_type, connection_error_type) as e:
                if pokus < LC_KBS_REFRENY_MAX_POKUSOV:
                    log_debug(
                        f"[LC-KBS] Dátum {datum_str}: sieťová chyba ({e}), "
                        f"skúšam znova ({pokus}/{LC_KBS_REFRENY_MAX_POKUSOV})."
                    )
                    _cakaj_s_moznostou_zrusenia(LC_KBS_REFRENY_RETRY_DELAY_S * pokus)
                    continue

                log_info(
                    f"[LC-KBS] Dátum {datum_str}: sieťová chyba aj po "
                    f"{LC_KBS_REFRENY_MAX_POKUSOV} pokusoch, refrén preskakujem."
                )
                return None

            except request_exception_type as e:
                # Sem padá napr. ChunkedEncodingError ("Response ended prematurely")
                # – ide o prerušenie spojenia, oplatí sa znova skúsiť.
                if pokus < LC_KBS_REFRENY_MAX_POKUSOV:
                    log_debug(
                        f"[LC-KBS] Dátum {datum_str}: požiadavka zlyhala ({e}), "
                        f"skúšam znova ({pokus}/{LC_KBS_REFRENY_MAX_POKUSOV})."
                    )
                    _cakaj_s_moznostou_zrusenia(LC_KBS_REFRENY_RETRY_DELAY_S * pokus)
                    continue

                log_info(f"[LC-KBS] Dátum {datum_str}: požiadavka zlyhala ({e}), refrén preskakujem.")
                return None

        return None

    except Exception as e:
        # Neočakávaná (nesieťová) chyba – nemá zmysel ju opakovať.
        log_exception(f"[LC-KBS] Neočakávaná chyba pri dátume {datum_str}", e)
        return None

    finally:
        # Zatvára sa VÝHRADNE session, ktorú si táto funkcia vytvorila sama
        # (session_vytvorena_lokalne). Session zdieľanú naprieč dávkou
        # (poslanú cez parameter `session`) zatvára jej vlastník –
        # _RefrenyKontext.zavri_session() na konci celej dávky.
        if session_vytvorena_lokalne and session is not None:
            try:
                session.close()
            except Exception:
                pass


def _vycisti_refren_zalmu_lc_kbs(text: str) -> str:
    t = html.unescape(text or "").strip()
    t = re.sub(r"^[Rr]\s*[.:]\s*", "", t).strip()
    t = t.lstrip(":. ").strip()
    t = re.sub(r":(?!\s)", ": ", t)
    t = re.sub(r"\s*alebo\s+[Aa]leluja\.?\s*$", "", t, flags=re.IGNORECASE).strip()
    t = _vycisti_text_lc_kbs(t)
    # Dve alternatívy refrénu (napr. ZOS): „alebo“ za koncom vety dáme na
    # samostatný riadok s prázdnym riadkom pred aj za ním.
    t = re.sub(r"(?<=[.!?…])[ \t]+alebo[ \t]+", "\n\nalebo\n\n", t)
    return t


def _extrahuj_refreny_zalmov_lc_kbs(soup) -> list[str]:
    """Extrahuje všetky refrény responzóriových žalmov zo stránky lc.kbs.sk."""
    if not soup:
        return []

    refreny = []
    seen = set()

    def pridaj(text: str):
        cisty = _vycisti_refren_zalmu_lc_kbs(text)
        if not cisty or len(cisty) < 5:
            return
        if cisty not in seen:
            refreny.append(cisty)
            seen.add(cisty)

    ignorujeme_zalm = False
    elementy = soup.find_all(["p", "h3", "h4", "h5", "strong", "b", "li", "em", "i"])

    for elem in elementy:
        text = elem.get_text(" ", strip=True)
        if len(text) < 2:
            continue

        low = text.lower()

        if text.strip().lower().startswith(("r.", "r:")):
            pridaj(text)
            if ignorujeme_zalm:
                continue

        if ignorujeme_zalm:
            normalized = normalize_diacritics(low)
            nadpisy = (
                "citanie z", "z listu", "zo skutkov", "evanjelium",
                "zaciatok", "prve citanie", "druhe citanie", "z knihy",
            )
            if any(normalized.startswith(nadpis) for nadpis in nadpisy):
                ignorujeme_zalm = False
            else:
                continue

        if normalize_diacritics(low).startswith(("responzoriovy zalm", "zalm")):
            ignorujeme_zalm = True
            continue

    if not refreny:
        try:
            for riadok in soup.get_text("\n").split("\n"):
                r = riadok.strip()
                if r.lower().startswith(("r.", "r:")) and len(r) > 5:
                    pridaj(r)
        except Exception as e:
            log_exception("[LC-KBS] Fallback extrakcia refrénu zlyhala", e)

    return refreny


def _vsetky_dni_roka(rok: int) -> list[date]:
    d = date(rok, 1, 1)
    end = date(rok, 12, 31)
    dni = []
    while d <= end:
        dni.append(d)
        d += timedelta(days=1)
    return dni


def _roky_podla_blizkosti(preferovany_rok: int, parita: int | None = None) -> list[int]:
    roky = range(CEZROCNE_TYZDNE_ROK_MIN, CEZROCNE_TYZDNE_ROK_MAX + 1)
    if parita is not None:
        roky = [rok for rok in roky if rok % 2 == parita]
    return sorted(roky, key=lambda rok: (abs(rok - preferovany_rok), rok))


def _najdi_datum_cezrocnej_nedele(tyzden: int, cyklus: str, preferovany_rok: int) -> date | None:
    """
    Nájde reprezentatívny dátum nedele pre daný cezročný týždeň a cyklus A/B/C.

    1. cezročná nedeľa sa liturgicky prekrýva s Krstom Pána; preto pre 1C
    sťahujeme nedeľné refrény zo sviatku Krstu Pána.
    """
    cyklus = cyklus.upper()
    for rok in _roky_podla_blizkosti(preferovany_rok):
        if tyzden == 1:
            datum = krst_krista_pana(rok)
            if vypocitaj_liturgicky_rok(datum) == cyklus:
                return datum
            continue

        for datum in _vsetky_dni_roka(rok):
            if (
                datum.weekday() == 6
                and vypocitaj_liturgicky_rok(datum) == cyklus
                and vypocitaj_kod_liturgickej_casti(datum) == f"{tyzden}C"
            ):
                return datum
    return None


def _najdi_datum_cezrocneho_vs_dna(tyzden: int, den_index: int, parita: int, preferovany_rok: int) -> date | None:
    """Nájde reprezentatívny feriálny dátum pre týždeň, deň Po-So a párnosť roka."""
    for rok in _roky_podla_blizkosti(preferovany_rok, parita=parita):
        for datum in _vsetky_dni_roka(rok):
            if datum.weekday() != den_index:
                continue
            if vypocitaj_kod_liturgickej_casti(datum) == f"{tyzden}C":
                return datum
    return None


def _stiahni_prvy_refren_lc_kbs_so_stavom(datum: date, session: Any = None) -> tuple[str | None, bool]:
    """
    Vráti (refrén alebo None, server_odpovedal).

    server_odpovedal=False  → sieťová/HTTP chyba (stránka sa vôbec nestiahla),
    server_odpovedal=True   → stránka sa stiahla; ak je refrén None, tak sa v nej
                              len nenašiel (iný problém ako výpadok servera).
    Circuit breaker (_RefrenyKontext.zaznamenaj_vysledok) tieto dva prípady
    rozlišuje – predtým ich zlučoval a hlásil „server neodpovedá“ aj pri
    úspešne stiahnutých stránkach bez refrénu.
    """
    soup = _stiahni_lc_kbs_soup(datum, session=session)
    refreny = _extrahuj_refreny_zalmov_lc_kbs(soup)
    return (refreny[0] if refreny else None), soup is not None


def stiahni_cezrocne_tyzdenne_refreny_pre_rok(rok: int, vystup_priecinok: Path, progress_callback=None) -> dict:
    ctx_or = _priprav_kontext_alebo_vrat_chybu(
        rok, vystup_priecinok, "backup_cezrocne", progress_callback,
        "[LC-KBS] Sťahovanie cezročných týždňov preskočené: chýbajú knižnice."
    )
    if isinstance(ctx_or, dict):
        return ctx_or
    ctx: _RefrenyKontext = ctx_or

    parita = 2 if rok % 2 == 0 else 1
    parita_roka = rok % 2
    parita_text = "párny" if parita == 2 else "nepárny"
    kody = [f"{t}C{parita}" for t in range(1, 35)]

    ctx.zalohuj_kody(kody)
    celkovo = 34 * (len(CEZROCNE_NEDIELNE_CYKLY) + len(CEZROCNE_DNI_TYZDNA))
    spracuj_slot = ctx.vytvor_spracuj_slot(celkovo, pocitaj_datumy_nezistene=True)

    ctx.progress(f"Začínam sťahovanie cezročných týždňov pre rok {rok}.", 0, celkovo)

    try:
        for tyzden in range(1, 35):
            ctx.aktualny_subor = f"{tyzden}C{parita}"
            bloky = [f"{tyzden}. TÝŽDEŇ CEZROČNÉHO OBDOBIA ({parita_text} rok)"]
            for cyklus in CEZROCNE_NEDIELNE_CYKLY:
                datum = _najdi_datum_cezrocnej_nedele(tyzden, cyklus, rok)
                bloky.append(f"{cyklus}: {spracuj_slot(f'{tyzden}C{parita} {cyklus}', datum)}")
            for cislo_dna, den_index in CEZROCNE_DNI_TYZDNA.items():
                datum = _najdi_datum_cezrocneho_vs_dna(tyzden, den_index, parita_roka, rok)
                bloky.append(f"{cislo_dna}. {spracuj_slot(f'{tyzden}C{parita} deň {cislo_dna}', datum)}")
            ctx.zapis_bloky(ctx.aktualny_subor, bloky)
    except _PredcasneUkoncenieStahovania as e:
        log_info(f"[LC-KBS] Cezročné týždenné refrény {rok}: predčasne ukončené – {e}")
    except _StahovanieZrusene:
        ctx.zrusene = True
        log_info("[LC-KBS] Sťahovanie zrušené (tlačidlo Zrušiť alebo ukončenie aplikácie) – zvyšok sa nestiahol.")
    finally:
        ctx.zavri_session()

    log_info(
        f"[LC-KBS] Cezročné týždenné refrény {rok} – súhrn: "
        f"spracovaných položiek {ctx.pocitadlo.aktualny_slot}/{celkovo}, chyby {ctx.pocitadlo.chyby}"
        + (f" ({', '.join(ctx.chybne_kody)})" if ctx.chybne_kody else "") + "."
    )
    ctx.progress(f"Hotovo. Spracovaných položiek: {ctx.pocitadlo.aktualny_slot}, chyby: {ctx.pocitadlo.chyby}.", ctx.pocitadlo.aktualny_slot, celkovo)

    return {
        "uspech": (ctx.pocitadlo.aktualny_slot - ctx.pocitadlo.chyby) > 0,
        **ctx.priznaky_prerusenia(),
        "celkovo": ctx.pocitadlo.aktualny_slot,
        "chyby": ctx.pocitadlo.chyby,
        "chybne_kody": ctx.chybne_kody,
        "datumy_nezistene": ctx.datumy_nezistene,
        "subory": ctx.zapisane,
        "zaloha": ctx.backup.retazec_alebo_none,
        "parita": parita,
    }


def _najdi_datum_nedele_v_obdobi(
    tyzden: int,
    cyklus: str,
    preferovany_rok: int,
    zaciatok_obdobia_fn: Callable[[int], date],
) -> "date | None":
    """
    Spoločná logika pre _najdi_datum_postnej_nedele, _najdi_datum_veľkonocnej_nedele
    a _najdi_datum_adventnej_nedele: nájde nedeľu n-tého týždňa liturgického obdobia
    (počítaného od zaciatok_obdobia_fn(rok)) v požadovanom cykle A/B/C.

    Ak by bolo pri budúcej úprave treba zmeniť túto logiku, stačí upraviť len tu –
    predtým mala každá z troch funkcií vlastnú (identickú) kópiu tohto cyklu.
    """
    cyklus = cyklus.upper()
    for rok in _roky_podla_blizkosti(preferovany_rok):
        zaciatok = zaciatok_obdobia_fn(rok)
        kandidat = zaciatok + timedelta(weeks=tyzden - 1)
        if kandidat.weekday() == 6 and vypocitaj_liturgicky_rok(kandidat) == cyklus:
            return kandidat
    return None


def _najdi_datum_vs_dna_v_obdobi(
    tyzden: int,
    den_index: int,
    preferovany_rok: int,
    zaciatok_obdobia_fn: Callable[[int], date],
    je_spravny_kod_fn: Callable[[str], bool],
) -> "date | None":
    """
    Spoločná logika pre _najdi_datum_postneho_vs_dna, _najdi_datum_veľkonocneho_vs_dna
    a _najdi_datum_adventneho_vs_dna: nájde feriálny deň (Po=0..So=5) v n-tom týždni
    liturgického obdobia a overí, že vypočítaný liturgický kód zodpovedá očakávanému
    (predikát `je_spravny_kod_fn`, lebo veľkonočný variant má výnimku pre NP).
    """
    for rok in _roky_podla_blizkosti(preferovany_rok):
        zaciatok = zaciatok_obdobia_fn(rok)
        zaciatok_tyzdna = zaciatok + timedelta(weeks=tyzden - 1)
        kandidat = zaciatok_tyzdna + timedelta(days=den_index + 1)
        kod = vypocitaj_kod_liturgickej_casti(kandidat)
        if je_spravny_kod_fn(kod):
            return kandidat
    return None


def _zaciatok_postneho_obdobia(rok: int) -> date:
    """Prvá pôstna nedeľa (Veľká noc – 42 dní), spoločný začiatok pre pôstne funkcie."""
    return velkonocna_nedela(rok) - timedelta(days=42)


def _najdi_datum_postnej_nedele(tyzden: int, cyklus: str, preferovany_rok: int) -> "date | None":
    """Nájde reprezentatívny dátum pôstnej nedele pre daný týždeň (1–5) a cyklus A/B/C."""
    return _najdi_datum_nedele_v_obdobi(
        tyzden, cyklus, preferovany_rok, zaciatok_obdobia_fn=_zaciatok_postneho_obdobia
    )


def _najdi_datum_postneho_vs_dna(tyzden: int, den_index: int, preferovany_rok: int) -> "date | None":
    """Nájde reprezentatívny feriálny dátum pôstneho týždňa (1–5) a dňa (Po=0..So=5)."""
    ocakavany = f"{tyzden}P"
    return _najdi_datum_vs_dna_v_obdobi(
        tyzden, den_index, preferovany_rok,
        zaciatok_obdobia_fn=_zaciatok_postneho_obdobia,
        je_spravny_kod_fn=lambda kod: kod == ocakavany,
    )


def _najdi_datum_pps_dna(posun_dni: int, preferovany_rok: int) -> "date | None":
    """
    Nájde reprezentatívny dátum dňa v týždni Popolcovej stredy (kód PPS),
    t. j. štvrtok (posun_dni=1), piatok (posun_dni=2) alebo sobota (posun_dni=3)
    po Popolcovej strede, pred 1. pôstnou nedeľou.
    """
    for rok in _roky_podla_blizkosti(preferovany_rok):
        velka_noc = velkonocna_nedela(rok)
        popolcova_streda = velka_noc - timedelta(days=46)
        kandidat = popolcova_streda + timedelta(days=posun_dni)
        if vypocitaj_kod_liturgickej_casti(kandidat) == "PPS":
            return kandidat
    return None



def _najdi_datum_veľkonocnej_nedele(tyzden: int, cyklus: str, preferovany_rok: int) -> "date | None":
    """Nájde reprezentatívny dátum veľkonočnej nedele pre daný týždeň (1–7) a cyklus A/B/C."""
    return _najdi_datum_nedele_v_obdobi(
        tyzden, cyklus, preferovany_rok, zaciatok_obdobia_fn=velkonocna_nedela
    )


def _najdi_datum_veľkonocneho_vs_dna(tyzden: int, den_index: int, preferovany_rok: int) -> "date | None":
    """Nájde feriálny dátum veľkonočného týždňa (2–7) a dňa (Po=0..So=5)."""
    ocakavany = "VOKT" if tyzden == 1 else f"{tyzden}VN"
    return _najdi_datum_vs_dna_v_obdobi(
        tyzden, den_index, preferovany_rok,
        zaciatok_obdobia_fn=velkonocna_nedela,
        je_spravny_kod_fn=lambda kod: kod == ocakavany or (tyzden == 6 and den_index == 3 and kod == "NP"),
    )


def _najdi_datum_adventnej_nedele(tyzden: int, cyklus: str, preferovany_rok: int) -> "date | None":
    """Nájde reprezentatívny dátum adventnej nedele pre daný týždeň (1–4) a cyklus A/B/C."""
    return _najdi_datum_nedele_v_obdobi(
        tyzden, cyklus, preferovany_rok, zaciatok_obdobia_fn=prva_adventna_nedela
    )


def _najdi_datum_adventneho_vs_dna(tyzden: int, den_index: int, preferovany_rok: int) -> "date | None":
    """Nájde feriálny dátum adventného týždňa (1–4) a dňa (Po=0..So=5)."""
    ocakavany = f"{tyzden}AD"
    return _najdi_datum_vs_dna_v_obdobi(
        tyzden, den_index, preferovany_rok,
        zaciatok_obdobia_fn=prva_adventna_nedela,
        je_spravny_kod_fn=lambda kod: kod == ocakavany,
    )


