        # --- BOX: Odporúčané piesne (killer feature) ---
        odporucane_box = tk.Frame(panel_vyber, bg="#1a1a1a", bd=0, highlightthickness=1, highlightbackground="#262626")
        odporucane_box.pack(fill=tk.X, pady=(0, 12), padx=0)

