            # Poradie záložiek: 1 Ovládanie, 2 Vyhľadávanie, 3 Úprava textov, 4 Priečinok piesní,
            # 5 Čítania, 6 Pomoc (frame5), 7 Web (frame6)
            frames = {1: frame1, 2: frame2, 3: frame3, 4: frame4, 5: frame_citania, 6: frame5, 7: frame6}
            font_size = tk.IntVar(value=self.about_font_size)
            text_widgets = []

            def _nastav_tagy_sekcii(tw, size):
                tw.tag_config(
                    "nadpis_sekcie",
                    font=(safe_font_name, size, "bold"),
                    foreground="white"
                )
                tw.tag_config(
                    "bodka",
                    font=(safe_font_name, size + 4, "bold"),
                    foreground="#d4a017"
                )
                tw.tag_raise("bodka", "nadpis_sekcie")

            def vlozit_text(parent, nazov: str, text: str):
                scrollbar = ttk.Scrollbar(
                    parent,
                    orient="vertical",
                    style="KinakDark.Vertical.TScrollbar"
                )
                scrollbar.pack(side=tk.RIGHT, fill=tk.Y)

                text_widget = tk.Text(
                    parent,
                    wrap="word",
                    font=(safe_font_name, font_size.get()),
                    fg=fg,
                    bg=bg,
                    padx=20,
                    pady=20,
                    relief="flat",
                    highlightthickness=0,
                    borderwidth=0,
                    yscrollcommand=scrollbar.set,
                    insertbackground=fg
                )
                text_widget.pack(fill=tk.BOTH, expand=True)
                scrollbar.config(command=text_widget.yview)

                text_widget.bind("<Button-1>", self._zablokovat_klik)
                text_widget.insert("1.0", f"{nazov}\n\n")
                text_widget.tag_add("nadpis", "1.0", "1.end")
                text_widget.tag_config(
                    "nadpis",
                    font=(safe_font_name, max(font_size.get() + 4, 12), "bold"),
                    foreground="white"
                )
                text_widget.insert("end", text)

                # Nadpisy sekcií (riadky so znakom ●): tučné písmo + väčšia farebná bodka
                _nastav_tagy_sekcii(text_widget, font_size.get())
                _pozicia = "1.0"
                while True:
                    _idx = text_widget.search("●", _pozicia, stopindex="end")
                    if not _idx:
                        break
                    text_widget.tag_add("nadpis_sekcie", _idx, f"{_idx} lineend")
                    text_widget.tag_add("bodka", _idx, f"{_idx}+1c")
                    _pozicia = f"{_idx}+1c"

                text_widget.config(state="disabled")

                text_widget.bind("<Enter>", lambda e, tw=text_widget: tw.bind_all(
                    "<MouseWheel>",
                    lambda ev, scroll_widget=tw: scroll_widget.yview_scroll(int(-1 * (ev.delta / 120)), "units")
                ))
                text_widget.bind("<Leave>", lambda e, tw=text_widget: tw.unbind_all("<MouseWheel>"))
                text_widgets.append(text_widget)
                return text_widget

